# BOMLine: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Bomline:
    bom_id: str = None  # BOM
    line: float = None  # Line #
    component_id: str = None  # Component
    qty_per: float = None  # Per parent
    uom: str = None  # Unit

REQUIRED = ["bom_id", "line", "component_id", "qty_per"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'bom_id': 'BOM-WIDGET-A', 'line': 10, 'component_id': 'MAT-STEEL-304', 'qty_per': 0.4, 'uom': 'kg'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

